public class HttpForm{}public class ResultData{public bool Succeed{get{return true;}}public string Error{get{return null;}}}public class FormManager{public static FormManager GetInstance(){return null;}public object Push(object form){return null;}}public static class SubForm{public static object MakeDialog(string text){return null;}}public static class Language{public static bool SetLanguagePack(string s,byte[] data,bool enabled=true){return true;}}public class LanguageForm{public int mode_;public static string langDownloadUrl_;public byte[] langDownloadData_;public static System.Threading.ThreadStart callback_;public System.Action<HttpForm,ResultData> Make(){return delegate(HttpForm form,ResultData data){if(data.Succeed){bool ready=Language.SetLanguagePack(langDownloadUrl_,langDownloadData_);if(ready&&callback_!=null){callback_();}}else{FormManager manager=FormManager.GetInstance();LanguageForm next=new LanguageForm();next.mode_=1;manager.Push(next);manager.Push(SubForm.MakeDialog(data.Error));}};}}